CREATE TABLE faultline.policy_retention_changes(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,actor_id text NOT NULL,base_policy_revision integer NOT NULL CHECK(base_policy_revision>0),policy_revision integer NOT NULL CHECK(policy_revision>base_policy_revision),previous_policy_hash text NOT NULL,policy_hash text NOT NULL,patch jsonb NOT NULL,impact jsonb NOT NULL,impact_hash text NOT NULL,reviewed_at timestamptz NOT NULL,effective_at timestamptz NOT NULL CHECK(effective_at>=reviewed_at),status text NOT NULL CHECK(status IN('scheduled','expiring','pending_cleanup','completed','cancelled')),revision integer NOT NULL DEFAULT 1,fence uuid,lease_until timestamptz,result jsonb NOT NULL DEFAULT '{}',error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE faultline.policy_expirations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,change_id uuid NOT NULL,case_id uuid,resource_kind text NOT NULL CHECK(resource_kind IN('raw_import','snapshot','evidence_artifact','report','report_export','audit')),resource_id uuid NOT NULL,binding jsonb NOT NULL,content_hash text NOT NULL,captured_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,object_keys jsonb NOT NULL DEFAULT '[]',status text NOT NULL CHECK(status IN('scheduled','expired_pending_cleanup','cleaned','retained_shared','blocked','cancelled')),expired_at timestamptz,cleaned_at timestamptz,error_code text,UNIQUE(workspace_id,change_id,resource_kind,resource_id),FOREIGN KEY(workspace_id,change_id) REFERENCES faultline.policy_retention_changes(workspace_id,id));
CREATE INDEX policy_retention_due ON faultline.policy_retention_changes(effective_at,id) WHERE status IN('scheduled','expiring','pending_cleanup');
CREATE INDEX policy_resource_expiry ON faultline.policy_expirations(workspace_id,resource_kind,resource_id,expires_at);
ALTER TABLE faultline.policy_retention_changes ENABLE ROW LEVEL SECURITY;ALTER TABLE faultline.policy_retention_changes FORCE ROW LEVEL SECURITY;
ALTER TABLE faultline.policy_expirations ENABLE ROW LEVEL SECURITY;ALTER TABLE faultline.policy_expirations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON faultline.policy_retention_changes USING(workspace_id::text=current_setting('faultline.workspace_id',true)) WITH CHECK(workspace_id::text=current_setting('faultline.workspace_id',true));
CREATE POLICY tenant_scope ON faultline.policy_expirations USING(workspace_id::text=current_setting('faultline.workspace_id',true)) WITH CHECK(workspace_id::text=current_setting('faultline.workspace_id',true));
CREATE POLICY retention_dispatch_authority ON faultline.policy_retention_changes TO faultline_authority USING(true) WITH CHECK(true);
GRANT SELECT ON faultline.policy_retention_changes TO faultline_authority;
CREATE FUNCTION faultline.policy_retention_routes() RETURNS TABLE(workspace_id uuid,id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,faultline AS $fn$
 SELECT workspace_id,id FROM faultline.policy_retention_changes WHERE status IN('scheduled','expiring','pending_cleanup') AND effective_at<=now() AND (lease_until IS NULL OR lease_until<now()) ORDER BY effective_at,id LIMIT 20
$fn$;
REVOKE ALL ON FUNCTION faultline.policy_retention_routes() FROM PUBLIC;ALTER FUNCTION faultline.policy_retention_routes() OWNER TO faultline_authority;GRANT EXECUTE ON FUNCTION faultline.policy_retention_routes() TO faultline_api;
GRANT SELECT,INSERT ON faultline.policy_retention_changes,faultline.policy_expirations TO faultline_api;
GRANT UPDATE(status,revision,fence,lease_until,result,error_code,updated_at) ON faultline.policy_retention_changes TO faultline_api;
GRANT UPDATE(status,expired_at,cleaned_at,error_code) ON faultline.policy_expirations TO faultline_api;
-- Logical expiry metadata only. No new DELETE authority or physical purge functions are installed.
